INSERT IGNORE INTO `goods` (`id`, `user_id`, `school_id`, `title`, `description`, `price`, `images`, `category_id`, `status`, `audit_status`, `view_count`) VALUES
(2, 2, 1, '高等数学同济第七版上下册', '大一用过的高数教材，笔记齐全，适合预习和复习，书页干净无涂鸦。', 25.00, 'https://picsum.photos/400/400?random=503', 2, 0, 1, 89),
(3, 3, 1, '宿舍神器床上书桌', '大学四年必备床上书桌，可折叠，带抽屉和杯架，八成新，毕业带不走便宜出。', 35.00, 'https://picsum.photos/400/400?random=504,https://picsum.photos/400/400?random=505', 3, 0, 1, 234),
(4, 4, 1, 'Nike Air Force 1 42码', '白色空军一号，42码，穿了几次有点小，鞋盒都在，支持验货，非真假问题不退。', 450.00, 'https://picsum.photos/400/400?random=506', 4, 0, 1, 312),
(5, 5, 1, '迪卡侬山地自行车', '迪卡侬入门级山地车，26寸，骑了半年左右，刹车变速都正常，适合日常通勤。', 600.00, 'https://picsum.photos/400/400?random=507,https://picsum.photos/400/400?random=508', 5, 0, 1, 178),
(6, 6, 1, '小米手环7 NFC版', '小米手环7 NFC版，支持门禁卡和公交卡，屏幕完好，表带正常使用痕迹，充电器齐全。', 150.00, 'https://picsum.photos/400/400?random=509', 1, 0, 1, 95),
(7, 7, 1, '英语四级真题试卷', '星火英语四级真题，做了两套就考过了，剩下的基本全新，附答案解析。', 15.00, 'https://picsum.photos/400/400?random=510', 2, 1, 1, 67),
(8, 8, 1, '懒人沙发豆袋椅', '宿舍懒人沙发，豆袋椅，灰色，可拆洗，九成新，买了没怎么用，占地儿出了。', 80.00, 'https://picsum.photos/400/400?random=511', 3, 0, 1, 145),
(9, 9, 1, '罗技G304无线鼠标', '罗技G304无线游戏鼠标，黑色，使用半年，功能正常，手感好，续航给力。', 180.00, 'https://picsum.photos/400/400?random=512', 1, 0, 1, 76),
(10, 10, 1, '瑜伽垫加厚15mm', 'TPE瑜伽垫，加厚15mm，加长加宽，紫色，几乎全新，买了没用几次就闲置了。', 45.00, 'https://picsum.photos/400/400?random=513', 5, 2, 1, 52),
(11, 1, 1, 'iPad Pro 2020 11寸 128G', 'iPad Pro 2020款 11寸 128G 深空灰，带妙控键盘和二代笔，平时用来记笔记看视频，因换新机出售。', 4200.00, 'https://picsum.photos/400/400?random=514,https://picsum.photos/400/400?random=515', 1, 0, 1, 267),
(12, 2, 1, '考研政治全家桶', '肖秀荣考研政治全家桶，1000题+精讲精练+肖四肖八，只写了几页，大部分全新。', 50.00, 'https://picsum.photos/400/400?random=516', 2, 0, 1, 123),
(13, 3, 1, '电煮锅小型1.5L', '宿舍小电锅，1.5L，可煮面煮粥，功率小不跳闸，用了一学期，毕业出。', 40.00, 'https://picsum.photos/400/400?random=517', 3, 0, 1, 189),
(14, 4, 1, 'Adidas Yeezy 350 43码', '椰子350 芝麻配色，43码，正品，穿了半年，鞋底有磨损，鞋面完好，诚心出。', 800.00, 'https://picsum.photos/400/400?random=518', 4, 0, 1, 345),
(15, 5, 1, '电动车爱玛小蜜豆', '爱玛小蜜豆电动车，48V，续航30公里左右，骑了一年多，车况良好，有牌照。', 1200.00, 'https://picsum.photos/400/400?random=519', 5, 0, 1, 456),
(16, 6, 1, 'AirPods Pro 第二代', 'AirPods Pro 二代，使用3个月，音质降噪都很棒，配件齐全，因换安卓出。', 1300.00, 'https://picsum.photos/400/400?random=520', 1, 0, 1, 234),
(17, 7, 1, '六级词汇书+真题', '新东方六级词汇词根+联想记忆法+历年真题，词汇书画了一些，真题全新没做。', 30.00, 'https://picsum.photos/400/400?random=521', 2, 0, 1, 78),
(18, 8, 1, '小冰箱单门50L', '宿舍迷你小冰箱，50L单门，可冷藏饮料水果，静音低功耗，毕业出。', 200.00, 'https://picsum.photos/400/400?random=522', 3, 0, 1, 312),
(19, 9, 1, 'Kindle Paperwhite 5', 'Kindle Paperwhite 第5代，6.8寸屏幕，8G内存，看电子书神器，95新。', 700.00, 'https://picsum.photos/400/400?random=523', 1, 0, 1, 167),
(20, 10, 1, '篮球斯伯丁官方7号', '斯伯丁官方正品7号篮球，PU材质，室内外通用，打了几次几乎全新。', 150.00, 'https://picsum.photos/400/400?random=524', 5, 0, 1, 89);
INSERT IGNORE INTO `lost_found` (`id`, `user_id`, `school_id`, `type`, `title`, `description`, `images`, `location`, `contact`, `status`, `create_time`) VALUES
(3, 3, 1, 0, '丢失黑色双肩包', '今天下午在图书馆二楼自习室丢了一个黑色双肩包，里面有课本和笔记本电脑，求好心人告知，重金感谢！', 'https://picsum.photos/400/400?random=701', '图书馆二楼', '13800138003', 0, '2024-01-15 14:30:00'),
(4, 4, 1, 1, '捡到一串钥匙', '在一教302教室捡到一串钥匙，上面有一个小熊挂件，失主请联系我认领。', 'https://picsum.photos/400/400?random=702', '一教302', '13800138004', 0, '2024-01-14 10:20:00'),
(5, 5, 1, 0, '校园卡丢失', '昨天在食堂丢失校园卡，卡号不记得了，名字叫张三，计算机学院，捡到请联系我，谢谢！', NULL, '一食堂', '13800138005', 0, '2024-01-13 12:15:00'),
(6, 6, 1, 1, '捡到一部苹果手机', '在操场看台上捡到一部白色苹果手机，有密码，已经交到保卫处了，失主可以去认领。', 'https://picsum.photos/400/400?random=703', '操场看台', '13800138006', 1, '2024-01-12 18:45:00'),
(7, 7, 1, 0, '学生证丢失', '学生证丢了，名字叫李四，学号2021xxxx，管理学院，捡到麻烦联系我，非常感谢！', NULL, '未知', '13800138007', 0, '2024-01-11 09:00:00'),
(8, 8, 1, 1, '捡到一个钱包', '在校车上捡到一个棕色钱包，里面有现金和银行卡，已交到校车上调度室。', 'https://picsum.photos/400/400?random=704', '校车（3号线）', '13800138008', 1, '2024-01-10 16:30:00'),
(9, 9, 1, 0, 'AirPods 丢失', 'AirPods Pro 丢了，白色充电盒，上面有一个贴纸，大概在宿舍到教学楼的路上丢的，找到必有重谢！', 'https://picsum.photos/400/400?random=705', '宿舍-教学楼路上', '13800138009', 0, '2024-01-09 08:20:00'),
(10, 10, 1, 1, '捡到一张身份证', '在南门附近捡到一张身份证，名字就不说了保护隐私，失主私信我确认信息后领取。', NULL, '南门', '13800138010', 0, '2024-01-08 17:00:00');
INSERT IGNORE INTO `activity` (`id`, `user_id`, `school_id`, `title`, `description`, `images`, `location`, `start_time`, `end_time`, `signup_deadline`, `max_participants`, `current_participants`, `status`, `category`, `view_count`) VALUES
(9, 3, 1, '编程马拉松大赛', '48小时不间断编程挑战，组队参赛，丰厚奖品等你来拿，欢迎所有编程爱好者！', 'https://picsum.photos/600/400?random=409', '创新创业中心', '2024-03-15 09:00:00', '2024-03-17 18:00:00', '2024-03-10 23:59:59', 100, 45, 1, 2, 567),
(10, 4, 1, '校园摄影大赛', '用镜头记录校园美好瞬间，主题"我的大学"，专业组和业余组分开评奖。', 'https://picsum.photos/600/400?random=410', '线上投稿', '2024-04-01 00:00:00', '2024-04-30 23:59:59', '2024-04-25 23:59:59', 999, 128, 1, 2, 890),
(11, 5, 1, '读书分享会', '每月一次的读书分享会，本月主题"成长"，欢迎带上你喜欢的书来交流。', 'https://picsum.photos/600/400?random=411', '图书馆多功能厅', '2024-02-25 19:00:00', '2024-02-25 21:00:00', '2024-02-24 23:59:59', 30, 18, 1, 3, 234),
(12, 6, 1, '创新创业讲座', '邀请知名校友分享创业经历，干货满满，还有互动问答环节，不容错过！', 'https://picsum.photos/600/400?random=412', '学术报告厅', '2024-03-05 14:00:00', '2024-03-05 17:00:00', '2024-03-04 23:59:59', 300, 256, 1, 3, 678);
